// Input: the JSON you pasted
// Output: clean array of contacts

function parseValue(v) {
  if (v.int) return parseInt(v.int, 10);
  if (v.string) return v.string;
  if (v.boolean) return v.boolean === "1" ? true : null; // treat "0" as null
  return null;
}

const values = items[0].json.methodResponse.params.param.value.array.data.value;

const contacts = values.map(v => {
  const obj = {};
  v.struct.member.forEach(m => {
    obj[m.name] = parseValue(m.value);
  });
  return obj;
});

return contacts.map(c => ({ json: c }));
